      "content": "#!/usr/bin/env python3
"""Convert CSV files to JSON."""
import argparse
import csv
import json
import sys


def convert(reader):
    """Convert a CSV file-like object to a list of dicts."""
    return list(csv.DictReader(reader))


def main():
    parser = argparse.ArgumentParser(description="Convert CSV to JSON")
    parser.add_argument("input", nargs="?", help="Input CSV file (reads stdin if omitted)")
    parser.add_argument("-o", "--output", help="Output JSON file (prints to stdout if omitted)")
    parser.add_argument("--pretty", action="store_true", help="Pretty-print JSON output")
    args = parser.parse_args()

    if args.input:
        with open(args.input, encoding="utf-8") as f:
            data = convert(f)
    else:
        data = convert(sys.stdin)

    indent = 2 if args.pretty else None
    result = json.dumps(data, indent=indent, ensure_ascii=False)

    if args.output:
        with open(args.output, "w", encoding="utf-8") as out:
            out.write(result + "\n")
    else:
        print(result)


if __name__ == "__main__":
    main()
