from pydantic import BaseModel
import sqlite3
from contextlib import contextmanager
from datetime import datetime

app = FastAPI(title="Items API")
DB_PATH = "items.db"


def init_db():
    with get_db() as db:
        db.execute(
            "CREATE TABLE IF NOT EXISTS items "
            "(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, "
            "description TEXT, price REAL NOT NULL, created_at TEXT NOT NULL)"
        )


@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
        conn.commit()
    finally:
        conn.close()


class ItemCreate(BaseModel):
    name: str
    description: str = ""
    price: float


class ItemResponse(BaseModel):
    id: int
    name: str
    description: str
    price: float
    created_at: str


@app.on_event("startup")
def startup():
    init_db()


@app.post("/items", response_model=ItemResponse, status_code=201)
def create_item(item: ItemCreate):
    now = datetime.utcnow().isoformat()
    with get_db() as db:
        cursor = db.execute(
            "INSERT INTO items (name, description, price, created_at) VALUES (?, ?, ?, ?)",
            (item.name, item.description, item.price, now),
        )
        return {"id": cursor.lastrowid, "name": item.name, "description": item.description, "price": item.price, "created_at": now}


@app.get("/items")
def list_items():
    with get_db() as db:
        rows = db.execute("SELECT * FROM items ORDER BY created_at DESC").fetchall()
        return [dict(r) for r in rows]


@app.get("/items/{item_id}", response_model=ItemResponse)
def get_item(item_id: int):
    with get_db() as db:
        row = db.execute("SELECT * FROM items WHERE id = ?", (item_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Item not found")
        return dict(row)


@app.delete("/items/{item_id}", status_code=204)
def delete_item(item_id: int):
    with get_db() as db:
        cursor = db.execute("DELETE FROM items WHERE id = ?", (item_id,))
        if cursor.rowcount == 0:
            raise HTTPException(status_code=404, detail="Item not found")
